import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# &packet.SetCommandsEnabled{Enabled: true}
ENABLED = bytes.fromhex("01")

# generated by gophertunnel b8bd735:
# &packet.SetCommandsEnabled{Enabled: false}
DISABLED = bytes.fromhex("00")

GOLDENS = [
    pytest.param(v2225.SetCommandsEnabledPacket(commands_enabled=True), ENABLED, id="enabled"),
    pytest.param(v2225.SetCommandsEnabledPacket(commands_enabled=False), DISABLED, id="disabled"),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_commands_enabled_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_commands_enabled_decodes_from_its_golden(packet, golden):
    assert v2225.SetCommandsEnabledPacket.from_bytes(golden) == packet


def test_set_commands_enabled_rejects_an_empty_body():
    with pytest.raises(ValueError, match="at byte"):
        v2225.SetCommandsEnabledPacket.from_bytes(b"")
